
 use super::beta::*;
 use std::path::{Path,PathBuf};
 struct NoCredentials;
 impl crate::secrets::CredentialStore for NoCredentials{fn load(&self,_:&crate::secrets::ServiceProfile)->Result<Option<crate::secrets::SecretBlob>,crate::secrets::StoreError>{panic!("local setup must not load account credentials")}fn save(&self,_:&crate::secrets::ServiceProfile,_:&crate::secrets::SecretBlob)->Result<(),crate::secrets::StoreError>{panic!("local setup must not save account credentials")}fn delete(&self,_:&crate::secrets::ServiceProfile)->Result<(),crate::secrets::StoreError>{panic!("local setup must not delete account credentials")}}
 #[test]#[ignore]fn beta_setup_actual_packaged_payload_offline_install_and_cold_state(){
  let package=PathBuf::from(std::env::var_os("NT2_BETA_PACKAGE").expect("uninstalled candidate package"));let original=PathBuf::from(std::env::var_os("NT2_BETA_ORIGINAL_GAME").expect("original game read-only source"));let resolved=Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..").canonicalize().unwrap();let repo=PathBuf::from(resolved.to_string_lossy().trim_start_matches(r"\\?\"));let own=repo.join("spikes/noita-entry/.build").join(format!("beta-install-actual-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(own.join("game")).unwrap();let game=own.join("game");for name in ["noita.exe","lua51.dll"]{std::fs::copy(original.join(name),game.join(name)).unwrap();}let user=own.join("user");std::fs::create_dir(&user).unwrap();std::fs::write(user.join("association-marker"),b"synthetic saved world association; preserve").unwrap();let a=nt2_desktop_g0::g3_social_installation::development_profile().unwrap();let preview=preview_with(&game,&package,&a,pairs).unwrap();install_with(&game,&package,&a,preview["token"].as_str().unwrap(),pairs,closed,verify_game).unwrap();
  let device=uuid::Uuid::new_v4();let core=||{let mut c=crate::next_client::Core::new(NoCredentials,device,std::sync::Arc::new(std::sync::Mutex::new(None)),user.join("consumed-worlds"));c.public_preferences(user.join("servers.json")).unwrap();c};let mut first=core();first.configure_game(game.to_str().unwrap()).unwrap();assert!(first.view()["game_path"].is_string());drop(first);let mut cold=core();cold.restore_local_installation();assert_eq!(cold.view()["game_path"],game.to_string_lossy().as_ref());assert_eq!(std::fs::read(user.join("association-marker")).unwrap(),b"synthetic saved world association; preserve");assert_eq!(crate::installation::hash(&original.join("noita.exe")).unwrap(),crate::installation::hash(&game.join("noita.exe")).unwrap());assert!(!game.join("mods/noita_together2/.nt2-local").exists());drop(cold);std::fs::remove_dir_all(own).unwrap();
 }
